'use strict';

/* ================================================================== *
 * Project Atlas
 *
 * Two data layers, never mixed:
 *   inventory.json — harvested facts, regenerated by scan.js
 *   verdicts.json  — your judgments only, written from this page
 * ================================================================== */

const $ = (sel) => document.querySelector(sel);

const state = {
  inventory: null,
  repos: [],
  verdicts: {},
  selectedKey: null,
  saveTimer: null,
  saving: false,
  sortCol: 'commits',
  sortDir: -1,
  filters: {
    search: '',
    group: 'owner',
    color: 'recency',
    hue: 'blue',
    size: 'sqrt-effort',
    showHidden: false,
  },
  panelPinned: false,
};

/* -------------------------------------------------------- vocabulary */

/* Status is ORDINAL — "how alive is this" — so it gets one hue stepped by
 * liveness, not five competing hues. Five adjacent categorical hues cannot
 * clear the colour-vision gates on a treemap (every tile touches every other),
 * but a validated ordinal ramp can, and the glyph carries exact identity. */
const STATUSES = [
  { id: 'active', label: 'Active', glyph: '●', step: 6, key: 'a' },
  { id: 'in-use', label: 'In use, not developed', glyph: '▣', step: 5, key: 'u' },
  { id: 'someday', label: 'Someday', glyph: '◔', step: 4, key: 's' },
  { id: 'done', label: 'Done', glyph: '✓', step: 3, key: 'd' },
  { id: 'dead', label: 'Dead', glyph: '✕', step: 2, key: 'x' },
];

/* Provenance IS categorical, and three is the documented ceiling for
 * all-pairs adjacency — which is exactly how many real values there are. */
const PROVENANCE = [
  { id: 'mine', label: 'Mine', glyph: '◆', hue: 'blue', varName: '--series-1', ink: '--series-1-ink' },
  { id: 'fork', label: 'Fork of someone else', glyph: '⑂', hue: 'orange', varName: '--series-2', ink: '--series-2-ink' },
  { id: 'external', label: "Clone of someone else's", glyph: '↓', hue: 'aqua', varName: '--series-3', ink: '--series-3-ink' },
  { id: 'unknown', label: 'Unknown', glyph: '?', hue: 'blue', varName: '--neutral', ink: '--neutral-ink' },
];

const ISSUE_BINS = [
  { max: 1, label: 'none' },
  { max: 3, label: '1–2' },
  { max: 6, label: '3–5' },
  { max: 16, label: '6–15' },
  { max: 41, label: '16–40' },
  { max: 101, label: '41–100' },
  { max: Infinity, label: '100 +' },
];

const PRIORITY_LABEL = { 3: 'High', 2: 'Medium', 1: 'Low', 0: 'None' };

const RECENCY_BINS = [
  { max: 7, label: 'past week' },
  { max: 30, label: '1–4 weeks' },
  { max: 90, label: '1–3 months' },
  { max: 180, label: '3–6 months' },
  { max: 365, label: '6–12 months' },
  { max: 730, label: '1–2 years' },
  { max: Infinity, label: '2 years +' },
];

const PRESENCE_LABEL = {
  both: 'Cloned & pushed',
  'local-only': 'Local only — never pushed',
  'remote-only': 'On GitHub — not cloned here',
};

const COMMON_TAGS = [
  'superseded', 'experiment', 'client work', 'archived upstream', 'reference only',
  'needs cleanup', 'no longer runs', 'merged elsewhere', 'personal',
];

/* ------------------------------------------------------------ helpers */

function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

function themeName() {
  return document.documentElement.dataset.theme === 'dark' ? 'dark' : 'light';
}

/** Steps of a validated single-hue ramp, index 0 = least, 6 = most. */
function rampSteps(hue) {
  const r = (window.ATLAS_RAMPS || {})[hue] || (window.ATLAS_RAMPS || {}).blue;
  return r ? r[themeName()] : ['#888', '#888', '#888', '#888', '#888', '#888', '#888'];
}

const _inkCache = new Map();
/** Pick black or white ink by whichever has more contrast on this fill. */
function inkOn(hex) {
  if (_inkCache.has(hex)) return _inkCache.get(hex);
  const c = hex.replace('#', '');
  const lum = [0, 2, 4]
    .map((i) => parseInt(c.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4))
    .reduce((s, v, i) => s + v * [0.2126, 0.7152, 0.0722][i], 0);
  const onWhite = 1.05 / (lum + 0.05);
  const onBlack = (lum + 0.05) / 0.05;
  const ink = onBlack >= onWhite ? '#0b0b0b' : '#ffffff';
  _inkCache.set(hex, ink);
  return ink;
}

function fromRamp(hue, step) {
  const bg = rampSteps(hue)[Math.max(0, Math.min(6, step))];
  return { bg, ink: inkOn(bg) };
}

const NEUTRAL = () => ({ bg: cssVar('--neutral'), ink: cssVar('--neutral-ink') });

function daysSince(iso) {
  if (!iso) return null;
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return null;
  return (Date.now() - t) / 86400000;
}

function recencyBin(iso) {
  const d = daysSince(iso);
  if (d === null) return null;
  for (let i = 0; i < RECENCY_BINS.length; i++) if (d < RECENCY_BINS[i].max) return i;
  return RECENCY_BINS.length - 1;
}

function fmtAgo(iso) {
  const d = daysSince(iso);
  if (d === null) return 'never';
  if (d < 1) return 'today';
  if (d < 2) return 'yesterday';
  if (d < 45) return `${Math.round(d)} days ago`;
  if (d < 365) return `${Math.round(d / 30.4)} months ago`;
  const y = d / 365.25;
  return `${y < 1.95 ? '1 year' : `${Math.round(y)} years`} ago`;
}

function fmtDate(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
}

function num(n) {
  return n === null || n === undefined ? '—' : n.toLocaleString();
}

function verdict(key) {
  return state.verdicts[key] || {};
}

/* ------------------------------------------------------------ scoring */

function sizeValue(r) {
  switch (state.filters.size) {
    case 'commits': return Math.max(r.commits || 0, 1);
    case 'sqrt-commits': return Math.sqrt(Math.max(r.commits || 0, 1));
    case 'issues': return Math.max(r.openIssues || 0, 1);
    case 'sqrt-issues': return Math.sqrt(Math.max(r.openIssues || 0, 1));
    case 'sqrt-files': return Math.sqrt(Math.max(r.trackedFiles || 0, 1));
    case 'equal': return 1;
    case 'sqrt-effort':
    default: return Math.sqrt(Math.max(r.effort || 0, 1));
  }
}

function issueBin(n) {
  if (n === null || n === undefined) return null;
  for (let i = 0; i < ISSUE_BINS.length; i++) if (n < ISSUE_BINS[i].max) return i;
  return ISSUE_BINS.length - 1;
}

/** Recency as a ramp step: 6 = touched this week, 0 = two years cold. */
function recencyStep(r) {
  const bin = recencyBin(r.lastActivity);
  return bin === null ? null : RECENCY_BINS.length - 1 - bin;
}

function colorFor(r) {
  const v = verdict(r.key);
  const hue = state.filters.hue;
  switch (state.filters.color) {
    case 'status': {
      const s = STATUSES.find((x) => x.id === v.status);
      return s ? fromRamp(hue, s.step) : NEUTRAL();
    }
    case 'provenance': {
      const p = PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3];
      return { bg: cssVar(p.varName), ink: cssVar(p.ink) };
    }
    // Bivariate: hue says whose it is, lightness says how recently you touched
    // it. Only three hues, which is exactly the all-pairs ceiling.
    case 'prov-recency': {
      const p = PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3];
      const step = recencyStep(r);
      return step === null ? NEUTRAL() : fromRamp(p.hue, step);
    }
    case 'issues': {
      const bin = issueBin(r.openIssues);
      return bin === null ? NEUTRAL() : fromRamp(hue, bin);
    }
    case 'priority': {
      const step = { 3: 6, 2: 4, 1: 2 }[v.priority];
      return step === undefined ? NEUTRAL() : fromRamp(hue, step);
    }
    case 'recency':
    default: {
      const step = recencyStep(r);
      return step === null ? NEUTRAL() : fromRamp(hue, step);
    }
  }
}

function groupOf(r) {
  switch (state.filters.group) {
    case 'provenance': {
      const p = PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3];
      return p.label;
    }
    case 'status': {
      const s = STATUSES.find((x) => x.id === verdict(r.key).status);
      return s ? s.label : 'Unsorted';
    }
    case 'presence': return PRESENCE_LABEL[r.presence] || r.presence;
    case 'language': return r.language || 'No language detected';
    case 'none': return `All ${state.repos.length} projects`;
    case 'owner':
    default: return r.group || 'Unaffiliated';
  }
}

function statusGlyph(r) {
  const s = STATUSES.find((x) => x.id === verdict(r.key).status);
  return s ? s.glyph : '';
}

function isStale(r) {
  const v = verdict(r.key);
  if (!v.markedAt || !v.seenLastCommit || !r.lastActivity) return false;
  return Date.parse(r.lastActivity) > Date.parse(v.seenLastCommit);
}

/* ---------------------------------------------------------- filtering */

function visibleRepos() {
  const q = state.filters.search.trim().toLowerCase();
  return state.repos.filter((r) => {
    const v = verdict(r.key);
    if (v.hidden && !state.filters.showHidden) return false;
    if (!q) return true;
    const hay = [
      r.name, r.owner, r.path, r.language, r.description, r.slug,
      ...(r.topics || []), ...(v.tags || []), v.note,
    ].filter(Boolean).join(' ').toLowerCase();
    return hay.includes(q);
  });
}

/* ----------------------------------------------------------- squarify */

function worstRatio(row, sum, short) {
  let max = -Infinity, min = Infinity;
  for (const it of row) { if (it.area > max) max = it.area; if (it.area < min) min = it.area; }
  const s2 = sum * sum, l2 = short * short;
  return Math.max((l2 * max) / s2, s2 / (l2 * min));
}

/** Squarified treemap. Mutates each item, adding .rect. */
function squarify(items, rect) {
  const r = { ...rect };
  let i = 0;
  while (i < items.length) {
    if (r.w <= 0.01 || r.h <= 0.01) {
      for (; i < items.length; i++) items[i].rect = { x: r.x, y: r.y, w: 0, h: 0 };
      return;
    }
    const short = Math.min(r.w, r.h);
    const row = [items[i]];
    let sum = items[i].area;
    let best = worstRatio(row, sum, short);
    let j = i + 1;
    while (j < items.length) {
      const nextSum = sum + items[j].area;
      row.push(items[j]);
      const nextWorst = worstRatio(row, nextSum, short);
      if (nextWorst > best) { row.pop(); break; }
      sum = nextSum;
      best = nextWorst;
      j++;
    }
    if (r.w >= r.h) {
      const rw = sum / r.h;
      let cy = r.y;
      for (const it of row) {
        const ih = it.area / rw;
        it.rect = { x: r.x, y: cy, w: rw, h: ih };
        cy += ih;
      }
      r.x += rw; r.w -= rw;
    } else {
      const rh = sum / r.w;
      let cx = r.x;
      for (const it of row) {
        const iw = it.area / rh;
        it.rect = { x: cx, y: r.y, w: iw, h: rh };
        cx += iw;
      }
      r.y += rh; r.h -= rh;
    }
    i = j;
  }
}

function layoutInto(nodes, rect) {
  const total = nodes.reduce((s, n) => s + n.value, 0);
  if (total <= 0 || rect.w <= 0 || rect.h <= 0) return [];
  const scale = (rect.w * rect.h) / total;
  const items = nodes
    .slice()
    .sort((a, b) => b.value - a.value)
    .map((n) => ({ node: n, area: n.value * scale }));
  squarify(items, rect);
  return items;
}

/* ------------------------------------------------------------- render */

const GROUP_HEAD = 19;
const GROUP_PAD = 3;
const GROUP_GAP = 4;

function render() {
  renderLegend();
  if ($('#btn-table').getAttribute('aria-pressed') === 'true') {
    renderTable();
    return;
  }
  renderTreemap();
}

function renderTreemap() {
  const host = $('#treemap');
  host.innerHTML = '';
  const repos = visibleRepos();

  if (!repos.length) {
    host.innerHTML = '<p class="empty-note">Nothing matches those filters.</p>';
    return;
  }

  const byGroup = new Map();
  for (const r of repos) {
    const g = groupOf(r);
    if (!byGroup.has(g)) byGroup.set(g, []);
    byGroup.get(g).push(r);
  }

  const groups = [...byGroup.entries()].map(([name, rs]) => ({
    name,
    repos: rs,
    value: rs.reduce((s, r) => s + sizeValue(r), 0),
  }));

  const W = host.clientWidth;
  const H = host.clientHeight;
  const placed = layoutInto(groups, { x: 0, y: 0, w: W, h: H });

  const frag = document.createDocumentFragment();

  for (const g of placed) {
    const { x, y, w, h } = g.rect;
    const gw = Math.max(w - GROUP_GAP, 0);
    const gh = Math.max(h - GROUP_GAP, 0);
    if (gw < 6 || gh < 6) continue;

    const box = document.createElement('div');
    box.className = 'group';
    box.style.cssText = `left:${x}px;top:${y}px;width:${gw}px;height:${gh}px`;

    const head = document.createElement('div');
    head.className = 'group-head';
    head.innerHTML =
      `<span>${escapeHTML(g.node.name)}</span>` +
      `<span class="group-count">${g.node.repos.length}</span>`;
    box.appendChild(head);

    const inner = {
      x: GROUP_PAD,
      y: GROUP_HEAD,
      w: gw - GROUP_PAD * 2,
      h: gh - GROUP_HEAD - GROUP_PAD,
    };

    if (inner.w > 4 && inner.h > 4) {
      const nodes = g.node.repos.map((r) => ({ repo: r, value: sizeValue(r) }));
      for (const item of layoutInto(nodes, inner)) {
        const tile = buildTile(item.node.repo, item.rect);
        if (tile) box.appendChild(tile);
      }
    }
    frag.appendChild(box);
  }

  host.appendChild(frag);
}

function buildTile(r, rect) {
  const w = Math.max(rect.w - 2, 0);
  const h = Math.max(rect.h - 2, 0);
  if (w < 2 || h < 2) return null;

  const v = verdict(r.key);
  const { bg, ink } = colorFor(r);

  const el = document.createElement('div');
  el.className = 'tile';
  if (r.presence !== 'both') el.classList.add(`presence-${r.presence}`);
  if (v.hidden) el.classList.add('is-hidden-row');
  if (r.key === state.selectedKey) el.classList.add('is-selected');
  if (w < 34 || h < 22) el.classList.add('is-tiny');
  else if (h < 38) el.classList.add('is-small');

  el.style.cssText =
    `left:${rect.x}px;top:${rect.y}px;width:${w}px;height:${h}px;` +
    `background:${bg};color:${ink}`;
  el.dataset.key = r.key;
  el.tabIndex = 0;
  el.setAttribute('role', 'button');
  el.setAttribute('aria-label',
    `${r.name}, ${r.owner || 'no owner'}, ${num(r.commits)} commits, last work ${fmtAgo(r.lastActivity)}` +
    (v.status ? `, marked ${v.status}` : '') + (v.hidden ? ', hidden' : ''));

  const flags = [
    statusGlyph(r),
    v.priority ? ['', '▁', '▄', '█'][v.priority] : '',
    r.duplicateOf ? '⧉' : '',
    r.dirtyFiles ? '✱' : '',
    r.unpushedCommits ? '↑' : '',
    r.isArchived ? '▤' : '',
  ].filter(Boolean).join(' ');

  // The subtitle tracks whatever the map is currently sized or coloured by,
  // so the number on the tile is the number you are looking at.
  const byIssues = /issues/.test(state.filters.size) || state.filters.color === 'issues';
  const lead = byIssues
    ? `${num(r.openIssues)} iss`
    : `${num(state.filters.size === 'sqrt-effort' ? r.effort : r.commits)}`;

  el.innerHTML =
    `<div class="tile-name">${escapeHTML(r.name)}</div>` +
    `<div class="tile-sub">${lead} · ${escapeHTML(fmtAgo(r.lastActivity))}</div>` +
    (flags ? `<div class="tile-flags">${escapeHTML(flags)}</div>` : '');

  return el;
}

function escapeHTML(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/* ------------------------------------------------------------- legend */

function renderLegend() {
  const host = $('#legend');
  const parts = [];
  const mode = state.filters.color;

  const hue = state.filters.hue;
  const ramp = (steps, h = hue) =>
    `<span class="legend-ramp">${steps
      .map((s) => `<span class="legend-swatch" style="background:${rampSteps(h)[s]}"></span>`)
      .join('')}</span>`;
  const unsorted = (label) =>
    `<span class="legend-item"><span class="legend-swatch" style="background:var(--neutral)"></span>${label}</span>`;

  if (mode === 'recency') {
    parts.push(
      `<span class="legend-label">Last work</span>${ramp([0, 1, 2, 3, 4, 5, 6])}` +
      `<span class="legend-note">2 yrs + &rarr; past week</span>` + unsorted('never')
    );
  } else if (mode === 'prov-recency') {
    parts.push(
      `<span class="legend-label">Whose &times; last work</span>` +
      PROVENANCE.slice(0, 3).map((p) =>
        `<span class="legend-item">${ramp([1, 3, 5, 6], p.hue)}${p.glyph} ${p.label}</span>`
      ).join('') +
      `<span class="legend-note">hue = whose it is, darker = touched more recently</span>`
    );
  } else if (mode === 'issues') {
    parts.push(
      `<span class="legend-label">Open issues</span>${ramp([0, 1, 2, 3, 4, 5, 6])}` +
      `<span class="legend-note">none &rarr; 100 +</span>` + unsorted('not on GitHub')
    );
  } else if (mode === 'status') {
    parts.push('<span class="legend-label">Status</span>' + STATUSES.map((s) =>
      `<span class="legend-item"><span class="legend-swatch" style="background:${rampSteps(hue)[s.step]}"></span>${s.glyph} ${s.label}</span>`
    ).join('') + unsorted('Unsorted'));
  } else if (mode === 'provenance') {
    parts.push('<span class="legend-label">Provenance</span>' + PROVENANCE.map((p) =>
      `<span class="legend-item"><span class="legend-swatch" style="background:var(${p.varName})"></span>${p.glyph} ${p.label}</span>`
    ).join(''));
  } else if (mode === 'priority') {
    parts.push('<span class="legend-label">Priority</span>' +
      [[6, 'High'], [4, 'Medium'], [2, 'Low']].map(([step, label]) =>
        `<span class="legend-item"><span class="legend-swatch" style="background:${rampSteps(hue)[step]}"></span>${label}</span>`
      ).join('') + unsorted('Unset'));
  }

  const sizeLabel = {
    'sqrt-effort': 'Area = √ commits by you (compressed; forks and clones shrink away)',
    'sqrt-commits': 'Area = √ all commits across every branch, including other people’s',
    commits: 'Area = all commits, linear (true proportion)',
    'sqrt-issues': 'Area = √ open issues',
    issues: 'Area = open issues, linear',
    'sqrt-files': 'Area = √ tracked files',
    equal: 'Area = equal (all tiles same size)',
  }[state.filters.size];

  parts.push(
    `<span class="legend-note">${sizeLabel}</span>` +
    `<span class="legend-item legend-note">` +
    `<span class="legend-swatch" style="background:transparent;border-style:dashed;border-color:var(--text-primary)"></span>local only` +
    `</span>` +
    `<span class="legend-item legend-note">` +
    `<span class="legend-swatch" style="background:transparent;border-style:dotted;border-color:var(--text-primary)"></span>not cloned` +
    `</span>` +
    `<span class="legend-note">✱ uncommitted · ↑ unpushed · ▤ archived</span>`
  );

  host.innerHTML = parts.join('<span></span>');
}

/* -------------------------------------------------------------- table */

const TABLE_COLS = [
  { key: 'name', label: 'Project' },
  { key: 'owner', label: 'Org' },
  { key: 'provenance', label: 'Provenance' },
  { key: 'presence', label: 'Where' },
  { key: 'commits', label: 'Commits', num: true },
  { key: 'lastActivity', label: 'Last work' },
  { key: 'openIssues', label: 'Issues', num: true },
  { key: 'openPRs', label: 'PRs', num: true },
  { key: 'status', label: 'Status' },
  { key: 'priority', label: 'Priority' },
  { key: 'tags', label: 'Tags' },
];

function renderTable() {
  const rows = visibleRepos().slice();
  const col = state.sortCol;
  rows.sort((a, b) => {
    const av = tableValue(a, col), bv = tableValue(b, col);
    if (av === bv) return a.name.localeCompare(b.name);
    if (av === null || av === undefined) return 1;
    if (bv === null || bv === undefined) return -1;
    return (av > bv ? 1 : -1) * state.sortDir;
  });

  $('#table-body').innerHTML = rows.map((r) => {
    const v = verdict(r.key);
    const s = STATUSES.find((x) => x.id === v.status);
    const p = PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3];
    return `<tr data-key="${escapeHTML(r.key)}">
      <td>${escapeHTML(r.name)}${v.hidden ? ' <span class="muted">(hidden)</span>' : ''}</td>
      <td>${escapeHTML(r.owner || '—')}</td>
      <td>${p.glyph} ${escapeHTML(p.label)}</td>
      <td>${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}</td>
      <td class="num">${num(r.commits)}</td>
      <td>${escapeHTML(fmtAgo(r.lastActivity))}</td>
      <td class="num">${num(r.openIssues)}</td>
      <td class="num">${num(r.openPRs)}</td>
      <td>${s ? `${s.glyph} ${escapeHTML(s.label)}` : '—'}</td>
      <td>${escapeHTML(PRIORITY_LABEL[v.priority || 0])}</td>
      <td>${escapeHTML((v.tags || []).join(', ') || '—')}</td>
    </tr>`;
  }).join('');
}

function tableValue(r, col) {
  const v = verdict(r.key);
  if (col === 'status') return v.status || '';
  if (col === 'priority') return v.priority || 0;
  if (col === 'tags') return (v.tags || []).join(',');
  return r[col];
}

/* -------------------------------------------------------------- panel */

function openPanel(key) {
  state.selectedKey = key;
  const r = state.repos.find((x) => x.key === key);
  if (!r) return;
  const v = verdict(key);

  const stale = isStale(r);
  const p = PROVENANCE.find((x) => x.id === r.provenance) || PROVENANCE[3];

  $('#panel-body').innerHTML = `
    <h2>${escapeHTML(r.name)}</h2>
    <div class="panel-org">${escapeHTML(r.slug || r.path || '')} · ${p.glyph} ${escapeHTML(p.label)}
      · ${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}${r.isArchived ? ' · archived' : ''}</div>
    ${r.description ? `<p class="panel-desc">${escapeHTML(r.description)}</p>` : ''}

    <div class="stat-row">
      <div class="stat"><div class="stat-label">Commits (all refs)</div>
        <div class="stat-value">${num(r.commits)}
          ${r.myCommits && r.commits ? `<small>${Math.round(r.myCommitShare * 100)}% yours</small>` : ''}</div></div>
      <div class="stat"><div class="stat-label">Last work</div>
        <div class="stat-value" style="font-size:14px">${escapeHTML(fmtAgo(r.lastActivity))}</div></div>
      <div class="stat"><div class="stat-label">Open issues</div>
        <div class="stat-value">${num(r.openIssues)}<small> · ${num(r.openPRs)} pr</small></div></div>
    </div>

    ${stale ? `<div class="stale">⚠ <strong>Your call here may be out of date.</strong>
      You marked this ${escapeHTML(fmtDate(v.markedAt))}. There has been new work since —
      the newest commit is now ${escapeHTML(fmtDate(r.lastActivity))}
      (${escapeHTML(fmtAgo(r.lastActivity))}), where it was
      ${escapeHTML(fmtDate(v.seenLastCommit))} when you judged it.</div>` : ''}

    ${r.duplicateOf ? `<div class="dup-note">⧉ <strong>This is a second working copy.</strong>
      ${r.clonesOfSlug} folders on this machine point at <code>${escapeHTML(r.slug)}</code>.
      Issue and PR counts are attributed to the copy with the most history, so they
      show as — here. A good candidate to hide.</div>` : ''}

    <div class="panel-section">
      <h3>Status</h3>
      <div class="seg" id="seg-status">
        ${STATUSES.map((s) => `<button type="button" data-status="${s.id}" aria-pressed="${v.status === s.id}">
          <span class="dot" style="background:${rampSteps(state.filters.hue)[s.step]}"></span>${s.glyph} ${s.label}</button>`).join('')}
        <button type="button" data-status="" aria-pressed="${!v.status}">Unsorted</button>
      </div>
    </div>

    <div class="panel-section">
      <h3>Priority</h3>
      <div class="seg" id="seg-priority">
        ${[3, 2, 1, 0].map((n) =>
          `<button type="button" data-priority="${n}" aria-pressed="${(v.priority || 0) === n}">${PRIORITY_LABEL[n]}</button>`).join('')}
      </div>
    </div>

    <div class="panel-section">
      <h3>Hide from the map</h3>
      <div class="seg">
        <button type="button" id="btn-hide" aria-pressed="${!!v.hidden}">
          ${v.hidden ? '◌ Hidden' : 'Hide this'}</button>
      </div>
      ${v.hidden ? `<div style="margin-top:7px">
        <input type="text" id="hide-reason" placeholder="Why hidden? (optional)"
               value="${escapeHTML(v.hiddenReason || '')}" list="tag-suggestions">
      </div>` : ''}
    </div>

    <div class="panel-section">
      <h3>Tags</h3>
      <div class="tag-list" id="tag-list">
        ${(v.tags || []).map((t) => `<span class="tag">${escapeHTML(t)}
          <button type="button" data-untag="${escapeHTML(t)}" aria-label="Remove ${escapeHTML(t)}">×</button></span>`).join('')
          || '<span class="muted">none</span>'}
      </div>
      <input type="text" id="tag-input" placeholder="Add a tag, press Enter" list="tag-suggestions">
      <datalist id="tag-suggestions">${COMMON_TAGS.map((t) => `<option value="${t}">`).join('')}</datalist>
    </div>

    <div class="panel-section">
      <h3>Note</h3>
      <textarea id="note-input" placeholder="What is this, why does it matter, what's next…">${escapeHTML(v.note || '')}</textarea>
    </div>

    <div class="panel-links">
      ${r.url ? `<a href="${escapeHTML(r.url)}" target="_blank" rel="noopener">GitHub ↗</a>` : ''}
      ${r.absPath ? `<button type="button" id="btn-reveal">Reveal in Finder</button>` : ''}
    </div>

    <div class="panel-section">
      <h3>Facts</h3>
      <dl class="kv">
        <dt>Path</dt><dd>${escapeHTML(r.path || '— not cloned —')}</dd>
        <dt>Branch</dt><dd>${escapeHTML(r.branch || '—')}</dd>
        <dt>On this branch</dt><dd>${num(r.commitsHead)}</dd>
        <dt>Local branches</dt><dd>${num(r.localBranches)}</dd>
        <dt>On GitHub default</dt><dd>${num(r.remoteCommits)}</dd>
        <dt>First commit</dt><dd>${escapeHTML(fmtDate(r.firstCommitDate))}</dd>
        <dt>Last commit</dt><dd>${escapeHTML(fmtDate(r.lastCommitDate))}</dd>
        <dt>Commits 90d</dt><dd>${num(r.commits90d)}</dd>
        <dt>Tracked files</dt><dd>${num(r.trackedFiles)}</dd>
        <dt>Uncommitted</dt><dd>${num(r.dirtyFiles)}</dd>
        <dt>Unpushed</dt><dd>${num(r.unpushedCommits)}</dd>
        <dt>Contributors</dt><dd>${num(r.contributors)}</dd>
        <dt>Language</dt><dd>${escapeHTML(r.language || '—')}</dd>
        <dt>Stars</dt><dd>${num(r.stars)}</dd>
        ${r.forkOf ? `<dt>Fork of</dt><dd>${escapeHTML(r.forkOf)}</dd>` : ''}
      </dl>
    </div>
  `;

  const wasHidden = $('#panel').hidden;
  $('#panel').hidden = false;
  wirePanel(r);
  // Opening the panel narrows the stage, so the map has to be re-laid out.
  if (wasHidden) renderTreemap();
  renderTreemapSelection();
}

function renderTreemapSelection() {
  document.querySelectorAll('.tile.is-selected').forEach((t) => t.classList.remove('is-selected'));
  const el = document.querySelector(`.tile[data-key="${CSS.escape(state.selectedKey || '')}"]`);
  if (el) el.classList.add('is-selected');
}

function closePanel(force = false) {
  if (state.panelPinned && !force) return;
  if ($('#panel').hidden) return;
  $('#panel').hidden = true;
  state.selectedKey = null;
  renderTreemap();
}

function setPinned(on) {
  state.panelPinned = on;
  localStorage.setItem('atlas-pin', on ? '1' : '0');
  $('#panel-pin').setAttribute('aria-pressed', String(on));
  $('#panel-pin').textContent = on ? '📌 Pinned' : '📌 Pin';
  $('#panel-pin').title = on
    ? 'Pinned — the panel stays open when you click away'
    : 'Pin the panel open (otherwise clicking away closes it)';
}

function wirePanel(r) {
  const body = $('#panel-body');

  body.querySelectorAll('#seg-status button').forEach((b) => {
    b.addEventListener('click', () => setVerdict(r, { status: b.dataset.status || undefined }));
  });
  body.querySelectorAll('#seg-priority button').forEach((b) => {
    b.addEventListener('click', () => setVerdict(r, { priority: +b.dataset.priority || undefined }));
  });

  const hideBtn = body.querySelector('#btn-hide');
  if (hideBtn) hideBtn.addEventListener('click', () => setVerdict(r, { hidden: !verdict(r.key).hidden }));

  const reason = body.querySelector('#hide-reason');
  if (reason) reason.addEventListener('change', () => setVerdict(r, { hiddenReason: reason.value }, false));

  const tagInput = body.querySelector('#tag-input');
  if (tagInput) {
    tagInput.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      e.preventDefault();
      const t = tagInput.value.trim();
      if (!t) return;
      const tags = [...new Set([...(verdict(r.key).tags || []), t])];
      setVerdict(r, { tags });
    });
  }
  body.querySelectorAll('[data-untag]').forEach((b) => {
    b.addEventListener('click', () => {
      const tags = (verdict(r.key).tags || []).filter((t) => t !== b.dataset.untag);
      setVerdict(r, { tags });
    });
  });

  const note = body.querySelector('#note-input');
  if (note) note.addEventListener('change', () => setVerdict(r, { note: note.value }, false));

  const reveal = body.querySelector('#btn-reveal');
  if (reveal) {
    reveal.addEventListener('click', () => {
      fetch('/api/open', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ absPath: r.absPath }),
      });
    });
  }
}

/* ------------------------------------------------------------ verdicts */

function setVerdict(r, patch, reopen = true) {
  const prev = state.verdicts[r.key] || {};
  const next = { ...prev, ...patch };

  for (const k of Object.keys(next)) {
    if (next[k] === undefined || next[k] === null || next[k] === '' ||
        (Array.isArray(next[k]) && !next[k].length) || next[k] === false) {
      delete next[k];
    }
  }

  const meaningful = Object.keys(next).some((k) => k !== 'markedAt' && k !== 'seenLastCommit');
  if (!meaningful) {
    delete state.verdicts[r.key];
  } else {
    next.markedAt = new Date().toISOString();
    next.seenLastCommit = r.lastActivity || null;
    if (!next.seenLastCommit) delete next.seenLastCommit;
    state.verdicts[r.key] = next;
  }

  scheduleSave();
  render();
  if (reopen) openPanel(r.key);
}

function scheduleSave() {
  clearTimeout(state.saveTimer);
  $('#save-state').textContent = 'unsaved…';
  state.saveTimer = setTimeout(save, 400);
}

async function save() {
  state.saving = true;
  try {
    const res = await fetch('/api/verdicts', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(state.verdicts),
    });
    const json = await res.json();
    $('#save-state').textContent = res.ok
      ? `saved · ${json.count} judged`
      : `save failed: ${json.error}`;
  } catch (err) {
    $('#save-state').textContent = 'save failed: ' + err.message;
  } finally {
    state.saving = false;
  }
}

/* ------------------------------------------------------------ tooltip */

const tip = () => $('#tooltip');

function showTooltip(r, ev) {
  const v = verdict(r.key);
  const s = STATUSES.find((x) => x.id === v.status);
  tip().innerHTML =
    `<div class="tt-name">${escapeHTML(r.name)}</div>` +
    `<div class="muted">${escapeHTML(r.slug || r.path || '')}</div>` +
    `<dl>
      <dt>Commits</dt><dd>${num(r.commits)}</dd>
      <dt>Last work</dt><dd>${escapeHTML(fmtAgo(r.lastActivity))}</dd>
      <dt>Open</dt><dd>${num(r.openIssues)} issues · ${num(r.openPRs)} PRs</dd>
      <dt>Where</dt><dd>${escapeHTML(PRESENCE_LABEL[r.presence] || r.presence)}</dd>
      ${s ? `<dt>Status</dt><dd>${s.glyph} ${escapeHTML(s.label)}</dd>` : ''}
      ${v.priority ? `<dt>Priority</dt><dd>${escapeHTML(PRIORITY_LABEL[v.priority])}</dd>` : ''}
      ${r.dirtyFiles ? `<dt>Uncommitted</dt><dd>${num(r.dirtyFiles)} files</dd>` : ''}
      ${r.unpushedCommits ? `<dt>Unpushed</dt><dd>${num(r.unpushedCommits)} commits</dd>` : ''}
      ${r.duplicateOf ? `<dt>⧉</dt><dd>duplicate of another clone</dd>` : ''}
      ${isStale(r) ? `<dt>⚠</dt><dd>new work since you judged it</dd>` : ''}
    </dl>`;
  tip().hidden = false;
  moveTooltip(ev);
}

function moveTooltip(ev) {
  const t = tip();
  const pad = 14;
  const rect = t.getBoundingClientRect();
  let x = ev.clientX + pad;
  let y = ev.clientY + pad;
  if (x + rect.width > window.innerWidth - 8) x = ev.clientX - rect.width - pad;
  if (y + rect.height > window.innerHeight - 8) y = ev.clientY - rect.height - pad;
  t.style.left = `${Math.max(8, x)}px`;
  t.style.top = `${Math.max(8, y)}px`;
}

/* --------------------------------------------------------------- wire */

function repoAt(el) {
  const tileEl = el.closest('[data-key]');
  if (!tileEl) return null;
  return state.repos.find((r) => r.key === tileEl.dataset.key) || null;
}

function wireGlobal() {
  const stage = $('#stage');

  stage.addEventListener('mouseover', (e) => {
    const r = repoAt(e.target);
    if (r) showTooltip(r, e);
  });
  stage.addEventListener('mousemove', (e) => {
    if (!tip().hidden) moveTooltip(e);
  });
  stage.addEventListener('mouseout', (e) => {
    if (!e.relatedTarget || !repoAt(e.relatedTarget)) tip().hidden = true;
  });
  stage.addEventListener('click', (e) => {
    const r = repoAt(e.target);
    if (r) openPanel(r.key);
    else closePanel(); // clicking bare map closes an unpinned panel
  });

  $('#table-body').addEventListener('click', (e) => {
    const r = repoAt(e.target);
    if (r) openPanel(r.key);
  });

  document.querySelectorAll('#table-view th').forEach((th, i) => {
    th.addEventListener('click', () => {
      const col = TABLE_COLS[i].key;
      if (state.sortCol === col) state.sortDir *= -1;
      else { state.sortCol = col; state.sortDir = -1; }
      renderTable();
    });
  });

  $('#panel-close').addEventListener('click', () => closePanel(true));
  $('#panel-pin').addEventListener('click', () => setPinned(!state.panelPinned));

  const bind = (sel, key, transform = (v) => v) =>
    $(sel).addEventListener('input', (e) => {
      state.filters[key] = transform(e.target.type === 'checkbox' ? e.target.checked : e.target.value);
      render();
    });

  bind('#f-search', 'search');
  bind('#f-group', 'group');
  bind('#f-size', 'size');
  bind('#f-hidden', 'showHidden');

  $('#f-color').addEventListener('input', (e) => {
    state.filters.color = e.target.value;
    localStorage.setItem('atlas-color', e.target.value);
    syncHueControl();
    render();
  });
  $('#f-hue').addEventListener('input', (e) => {
    state.filters.hue = e.target.value;
    localStorage.setItem('atlas-hue', e.target.value);
    render();
  });

  $('#btn-table').addEventListener('click', (e) => {
    const on = e.target.getAttribute('aria-pressed') !== 'true';
    e.target.setAttribute('aria-pressed', String(on));
    $('#table-view').hidden = !on;
    $('#stage').hidden = on;
    render();
  });

  // Clicking anywhere that isn't the map, the panel, or the controls dismisses
  // an unpinned panel.
  document.addEventListener('mousedown', (e) => {
    if (state.panelPinned || $('#panel').hidden) return;
    if (e.target.closest('#panel, .tile, .bar, #table-view')) return;
    closePanel();
  });

  $('#btn-theme').addEventListener('click', () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('atlas-theme', next);
    render();
  });

  $('#btn-export').addEventListener('click', () => {
    const blob = new Blob([JSON.stringify(state.verdicts, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'verdicts.json';
    a.click();
    URL.revokeObjectURL(a.href);
  });

  document.addEventListener('keydown', (e) => {
    const tag = document.activeElement && document.activeElement.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    if (e.key === 'Escape') { closePanel(true); return; }
    if (!state.selectedKey || e.metaKey || e.ctrlKey || e.altKey) return;
    const r = state.repos.find((x) => x.key === state.selectedKey);
    if (!r) return;

    const map = {
      '1': () => setVerdict(r, { priority: 1 }),
      '2': () => setVerdict(r, { priority: 2 }),
      '3': () => setVerdict(r, { priority: 3 }),
      '0': () => setVerdict(r, { priority: undefined }),
      h: () => setVerdict(r, { hidden: !verdict(r.key).hidden }),
      p: () => setPinned(!state.panelPinned),
    };
    for (const s of STATUSES) map[s.key] = () => setVerdict(r, { status: s.id });

    const fn = map[e.key.toLowerCase()];
    if (fn) { e.preventDefault(); fn(); }
  });

  let rt;
  window.addEventListener('resize', () => {
    clearTimeout(rt);
    rt = setTimeout(render, 120);
  });
}

/* --------------------------------------------------------------- boot */

/** The palette picker only means anything for single-hue encodings. */
function syncHueControl() {
  const usesRamp = ['recency', 'issues', 'status', 'priority'].includes(state.filters.color);
  $('#ctl-hue').style.display = usesRamp ? '' : 'none';
}

/**
 * Repos used to be keyed by GitHub slug, which collided whenever two folders
 * held clones of one repo. Keys are now paths. Adopt any orphaned slug-keyed
 * verdict onto the clone that carries that slug's history.
 */
function migrateVerdicts(verdicts, repos) {
  const live = new Set(repos.map((r) => r.key));
  const primaryBySlug = new Map();
  for (const r of repos) {
    if (r.slug && r.isPrimaryClone) primaryBySlug.set(`gh:${r.slug}`, r.key);
  }
  let moved = 0;
  for (const oldKey of Object.keys(verdicts)) {
    if (live.has(oldKey)) continue;
    const newKey = primaryBySlug.get(oldKey);
    if (!newKey || verdicts[newKey]) continue;
    verdicts[newKey] = verdicts[oldKey];
    delete verdicts[oldKey];
    moved++;
  }
  if (moved) scheduleSave();
  return verdicts;
}

async function boot() {
  const saved = localStorage.getItem('atlas-theme');
  document.documentElement.dataset.theme =
    saved || (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');

  let payload;
  try {
    // A self-contained snapshot can inline its data instead of calling the API.
    // Saves are no-ops in that mode.
    payload = window.__ATLAS_DATA__;
    if (!payload) {
      const res = await fetch('/api/data');
      payload = await res.json();
      if (!res.ok) throw new Error(payload.error || res.statusText);
    }
  } catch (err) {
    $('#treemap').innerHTML =
      `<p class="empty-note">Could not load inventory.<br><br>${escapeHTML(err.message)}<br><br>` +
      `Run <code>npm run scan</code>, then reload.</p>`;
    return;
  }

  state.inventory = payload.inventory;
  state.repos = payload.inventory.repos;
  state.verdicts = migrateVerdicts(payload.verdicts || {}, state.repos);

  // Restore what you last chose to look at.
  state.filters.color = localStorage.getItem('atlas-color') || state.filters.color;
  state.filters.hue = localStorage.getItem('atlas-hue') || state.filters.hue;
  $('#f-color').value = state.filters.color;
  $('#f-hue').value = state.filters.hue;
  setPinned(localStorage.getItem('atlas-pin') === '1');
  syncHueControl();

  const c = payload.inventory.counts;
  $('#scan-stamp').textContent =
    `${c.total} projects · ${num(c.openIssues)} open issues · ${c.localOnly} local-only · ` +
    `${c.remoteOnly} not cloned · ${c.duplicateClones} duplicate clones · ` +
    `scanned ${fmtAgo(payload.inventory.generatedAt)}`;
  $('#save-state').textContent = `${Object.keys(state.verdicts).length} judged`;

  wireGlobal();
  render();
}

boot();
